gqB(){return"\u041d\u0430\u0436\u043c\u0438\u0442\u0435 \u043a\u043d\u043e\u043f\u043a\u0443, \u0441\u043e\u043e\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u044e\u0449\u0443\u044e \u0446\u0435\u043b\u0435\u0432\u043e\u0439 \u0447\u0430\u0441\u0442\u043e\u0442\u0435 \u0441\u0432\u0435\u0442\u043e\u0432\u043e\u0433\u043e \u0438\u043c\u043f\u0443\u043b\u044c\u0441\u0430."},
gn2(){return"Yajilin"},
gn1(){return"\u0420\u0430\u0441\u043f\u043e\u043b\u043e\u0436\u0438\u0442\u0435 \u0447\u0435\u0440\u043d\u044b\u0435 \u043a\u043b\u0435\u0442\u043a\u0438 \u0438 \u043d\u0430\u0440\u0438\u0441\u0443\u0439\u0442\u0435 \u043e\u0434\u043d\u0443 \u043f\u0435\u0442\u043b\u044e, \u0441\u043e\u043e\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u044e\u0449\u0443\u044e \u043f\u043e\u0434\u0441\u043a\u0430\u0437\u043a\u0430\u043c."},
gkt(){return"Heyawake"},
gks(){return"\u041a\u043e\u043c\u043d\u0430\u0442\u044b \u0441 \u0437\u0430\u0442\u0435\u043d\u0435\u043d\u043d\u043e\u0439 \u0441\u0435\u0442\u043a\u043e\u0439 \u0431\u0435\u0437 \u0441\u043e\u0441\u0435\u0434\u043d\u0438\u0445 \u0447\u0435\u0440\u043d\u044b\u0445 \u044f\u0447\u0435\u0435\u043a."},
gtP(){return"\u0422\u0435\u043d\u043d\u0435\u0440 \u0413\u0440\u0438\u0434"},
gtO(){return"\u0417\u0430\u043f\u043e\u043b\u043d\u0438\u0442\u0435 \u0441\u0442\u0440\u043e\u043a\u0438 \u0446\u0438\u0444\u0440\u0430\u043c\u0438 0\u20139, \u0441\u043e\u043e\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u044e\u0449\u0438\u043c\u0438 \u0438\u0442\u043e\u0433\u043e\u0432\u044b\u043c \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f\u043c \u0441\u0442\u043e\u043b\u0431\u0446\u043e\u0432."},
gqP(){return"\u0421\u0443\u043c\u043c\u044b \u041a\u0430\u043a\u0443\u0440\u0430\u0441\u0443"},
gqO(){return"\u0417\u0430\u0448\u0442\u0440\u0438\u0445\u0443\u0439\u0442\u0435 \u044f\u0447\u0435\u0439\u043a\u0438, \u0447\u0442\u043e\u0431\u044b \u043e\u043d\u0438 \u0441\u043e\u043e\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u043e\u0432\u0430\u043b\u0438 \u0432\u0437\u0432\u0435\u0448\u0435\u043d\u043d\u044b\u043c \u0441\u0443\u043c\u043c\u0430\u043c \u0438\u043d\u0434\u0435\u043a\u0441\u043e\u0432 \u0441\u0442\u0440\u043e\u043a/\u0441\u0442\u043e\u043b\u0431\u0446\u043e\u0432."},
gtV(){return"\u0422\u0440\u043e\u0439\u043d\u044f\u0448\u043a\u0438 \u0442\u0440\u0438\u043e"},
gtU(){return"\u0417\u0430\u043f\u043e\u043b\u043d\u0438\u0442\u0435 \u0441\u0435\u0442\u043a\u0443 \u0442\u0440\u0435\u043c\u044f \u0444\u0438\u0433\u0443\u0440\u0430\u043c\u0438, \u0438\u0437\u0431\u0435\u0433\u0430\u044f \u0444\u0438\u0433\u0443\u0440 \xab\u0442\u0440\u0438 \u0432 \u0440\u044f\u0434\xbb."},
grg(){return"\u0421\u043e\u043f\u043e\u0441\u0442\u0430\u0432\u0438\u0442\u0435\u043b\u044c \u043c\u0430\u0442\u0440\u0438\u0446"},
grf(){return"\u0423\u043c\u043d\u043e\u0436\u044c\u0442\u0435 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f \u0441\u0442\u0440\u043e\u043a \u0438 \u0441\u0442\u043e\u043b\u0431\u0446\u043e\u0432, \u0447\u0442\u043e\u0431\u044b \u043e\u043d\u0438 \u0441\u043e\u043e\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u043e\u0432\u0430\u043b\u0438 \u0446\u0435\u043b\u0435\u0432\u043e\u043c\u0443 \u0441\u043a\u0430\u043b\u044f\u0440\u043d\u043e\u043c\u0443 \u043f\u0440\u043e\u0438\u0437\u0432\u0435\u0434\u0435\u043d\u0438\u044e."},
gtm(){return"\u0414\u0435\u0440\u0435\u0432\u044c\u044f \u043f\u0440\u043e\u0441\u0442\u044b\u0445 \u0444\u0430\u043a\u0442\u043e\u0440\u043e\u0432"},
gtl(){return"\u0420\u0430\u0437\u043b\u043e\u0436\u0438\u0442\u0435 \u0441\u043e\u0441\u0442\u0430\u0432\u043d\u044b\u0435 \u0447\u0438\u0441\u043b\u0430 \u043d\u0430 \u043f\u0430\u0440\u044b \u043f\u0440\u043e\u0441\u0442\u044b\u0445 \u043b\u0438\u0441\u0442\u044c\u0435\u0432."},
gu5(){return"\u0432\u0435\u043a\u0442\u043e\u0440 \u0432\u0435\u043a\u0442\u043e\u0440"},
gu4(){return"\u041c\u0430\u0441\u0448\u0442\u0430\u0431\u0438\u0440\u0443\u0439\u0442\u0435 \u0432\u0435\u043a\u0442\u043e\u0440\u044b, \u0447\u0442\u043e\u0431\u044b \u0438\u0445 \u0441\u0443\u043c\u043c\u0430 \u043f\u043e\u043f\u0430\u043b\u0430 \u0432 \u0446\u0435\u043b\u044c."},
goX(){return"\u0411\u0438\u043d\u043e\u043c\u0438\u0430\u043b\u044c\u043d\u043e\u0435 \u0441\u043e\u0432\u043f\u0430\u0434\u0435\u043d\u0438\u0435"},
goW(){return"\u0421\u043e\u043f\u043e\u0441\u0442\u0430\u0432\u044c\u0442\u0435 \u043a\u0432\u0430\u0434\u0440\u0430\u0442\u0438\u0447\u043d\u044b\u0435 \u0444\u043e\u0440\u043c\u0443\u043b\u044b \u0441 \u0444\u0430\u043a\u0442\u043e\u0440\u0438\u0437\u043e\u0432\u0430\u043d\u043d\u044b\u043c\u0438 \u0431\u0438\u043d\u043e\u043c\u0438\u0430\u043b\u044c\u043d\u044b\u043c\u0438 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f\u043c\u0438."},
gt5(){return"\u041f\u0440\u043e\u0446\u0435\u043d\u0442 \u043f\u043e\u043a\u0443\u043f\u043e\u043a"},
