gpL(){return"\u041a\u0440\u0438\u043f\u0442\u043e-\u0430\u0440\u0438\u0444\u043c\u0435\u0442\u0438\u043a\u0430"},
gpK(){return"\u0412\u0437\u043b\u043e\u043c\u0430\u0442\u044c \u043c\u0430\u0442\u0435\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u0437\u0430\u0434\u0430\u0447\u0438 \u0448\u0438\u0444\u0440\u0430 \u0437\u0430\u043c\u0435\u043d\u044b \u0441\u0438\u043c\u0432\u043e\u043b\u043e\u0432 \u0438 \u0446\u0438\u0444\u0440."},
gqA(){return"\u0414\u0440\u043e\u0431\u043d\u0430\u044f \u043f\u0438\u0446\u0446\u0430"},
gqz(){return"\u0420\u0430\u0437\u0434\u0435\u043b\u0438\u0442\u0435 \u043a\u0443\u0441\u043e\u0447\u043a\u0438 \u043f\u0438\u0446\u0446\u044b \u0442\u0430\u043a, \u0447\u0442\u043e\u0431\u044b \u043e\u043d\u0438 \u0441\u043e\u043e\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u043e\u0432\u0430\u043b\u0438 \u0446\u0435\u043b\u0435\u0432\u044b\u043c \u0434\u043e\u043b\u044f\u043c \u0441\u0443\u043c\u043c\u044b."},
grL(){return"\u0427\u0438\u0441\u043b\u043e\u0432\u044b\u0435 \u043e\u0431\u043b\u0438\u0433\u0430\u0446\u0438\u0438"},
grK(){return"\u0421\u0432\u044f\u0436\u0438\u0442\u0435 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f \u0443\u0437\u043b\u043e\u0432, \u0447\u0442\u043e\u0431\u044b \u043e\u043d\u0438 \u0440\u0430\u0432\u043d\u044f\u043b\u0438\u0441\u044c \u0441\u0443\u043c\u043c\u0435 \u0446\u0435\u043b\u0435\u0432\u043e\u0433\u043e \u0441\u043e\u0435\u0434\u0438\u043d\u0435\u043d\u0438\u044f."},
goV(){return"\u0411\u0430\u043b\u0430\u043d\u0441 \u0434\u0432\u043e\u0438\u0447\u043d\u043e\u0439 \u0448\u043a\u0430\u043b\u044b"},
goU(){return"\u0421\u0431\u0430\u043b\u0430\u043d\u0441\u0438\u0440\u0443\u0439\u0442\u0435 \u0434\u0435\u0441\u044f\u0442\u0438\u0447\u043d\u044b\u0439 \u0432\u0435\u0441, \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u044f \u0431\u043b\u043e\u043a\u0438 \u0441\u0442\u0435\u043f\u0435\u043d\u0438 \u0434\u0432\u043e\u0439\u043a\u0438."},
grt(){return"\u041f\u0443\u0442\u044c \u043f\u043e \u043c\u043e\u0434\u0443\u043b\u044e"},
grs(){return"\u041e\u0431\u0445\u043e\u0434 \u044f\u0447\u0435\u0435\u043a \u0441\u0435\u0442\u043a\u0438, \u0441\u043e\u043e\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u044e\u0449\u0438\u0445 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f\u043c \u043e\u0441\u0442\u0430\u0442\u043a\u0430 \u043f\u043e \u043c\u043e\u0434\u0443\u043b\u044e."},
gpX(){return"\u0423\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044f \u0437\u0430\u043c\u0435\u043d\u044b \u0446\u0438\u0444\u0440"},
gpW(){return"\u041f\u043e\u043c\u0435\u043d\u044f\u0439\u0442\u0435 \u043c\u0435\u0441\u0442\u0430\u043c\u0438 \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u044b\u0435 \u0446\u0438\u0444\u0440\u044b \u0432 \u0443\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044f\u0445, \u0447\u0442\u043e\u0431\u044b \u0438\u0441\u043f\u0440\u0430\u0432\u0438\u0442\u044c \u043e\u0431\u0430."},
goH(){return"\u041f\u043b\u043e\u0449\u0430\u0434\u044c \u0438 \u043f\u0435\u0440\u0438\u043c\u0435\u0442\u0440"},
goG(){return"\u041d\u0430\u0440\u0438\u0441\u0443\u0439\u0442\u0435 \u043f\u0440\u044f\u043c\u043e\u0443\u0433\u043e\u043b\u044c\u043d\u0438\u043a\u0438, \u0441\u043e\u043e\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u044e\u0449\u0438\u0435 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f\u043c \u0446\u0435\u043b\u0435\u0432\u043e\u0439 \u043f\u043b\u043e\u0449\u0430\u0434\u0438 \u0438 \u043f\u0435\u0440\u0438\u043c\u0435\u0442\u0440\u0430."},
gqH(){return"\u0411\u0430\u043b\u0430\u043d\u0441 \u043d\u0435\u0440\u0430\u0432\u0435\u043d\u0441\u0442\u0432\u0430"},
gqG(){return"\u041f\u043e\u043c\u0435\u0441\u0442\u0438\u0442\u0435 \u0441\u0438\u043c\u0432\u043e\u043b\u044b \u043d\u0435\u0440\u0430\u0432\u0435\u043d\u0441\u0442\u0432\u0430 \u043c\u0435\u0436\u0434\u0443 \u0441\u043b\u043e\u0436\u043d\u044b\u043c\u0438 \u043c\u0430\u0442\u0435\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u043c\u0438 \u0442\u0435\u0440\u043c\u0438\u043d\u0430\u043c\u0438."},
gng(){return"\u0413\u0440\u0430\u0444\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u043f\u043b\u043e\u0442\u0442\u0435\u0440"},
gnf(){return"\u041f\u043e\u0441\u0442\u0440\u043e\u0439\u0442\u0435 \u043a\u043e\u043e\u0440\u0434\u0438\u043d\u0430\u0442\u044b \u0441\u0435\u0442\u043a\u0438, \u0441\u043e\u043e\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u044e\u0449\u0438\u0435 \u043b\u0438\u043d\u0435\u0439\u043d\u044b\u043c/\u043a\u0432\u0430\u0434\u0440\u0430\u0442\u0438\u0447\u043d\u044b\u043c \u043a\u0440\u0438\u0432\u044b\u043c."},
goP(){return"\u0411\u0430\u0437\u043e\u0432\u0430\u044f \u043a\u043e\u043d\u0432\u0435\u0440\u0441\u0438\u044f"},
goO(){return"\u041f\u0440\u0435\u043e\u0431\u0440\u0430\u0437\u043e\u0432\u0430\u043d\u0438\u0435 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0439 \u043c\u0435\u0436\u0434\u0443 \u0434\u0432\u043e\u0438\u0447\u043d\u044b\u043c\u0438, \u0434\u0435\u0441\u044f\u0442\u0438\u0447\u043d\u044b\u043c\u0438, \u0448\u0435\u0441\u0442\u043d\u0430\u0434\u0446\u0430\u0442\u0435\u0440\u0438\u0447\u043d\u044b\u043c\u0438 \u0438 \u0432\u043e\u0441\u044c\u043c\u0435\u0440\u0438\u0447\u043d\u044b\u043c\u0438."},
gu0(){return"\u041a\u043e\u043d\u0432\u0435\u0440\u0442\u0435\u0440 \u0435\u0434\u0438\u043d\u0438\u0446 \u0438\u0437\u043c\u0435\u0440\u0435\u043d\u0438\u044f"},
gu_(){return"\u041e\u0442\u0432\u0435\u0447\u0430\u0439\u0442\u0435 \u043d\u0430 \u0431\u044b\u0441\u0442\u0440\u044b\u0435 \u043f\u0440\u0435\u043e\u0431\u0440\u0430\u0437\u043e\u0432\u0430\u043d\u0438\u044f \u0435\u0434\u0438\u043d\u0438\u0446 \u0438\u0437\u043c\u0435\u0440\u0435\u043d\u0438\u044f \u0432 \u0440\u0430\u043c\u043a\u0430\u0445 \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u0439 \u043f\u043e \u0432\u0440\u0435\u043c\u0435\u043d\u0438."},
gtC(){return"\u0418\u043d\u0441\u043f\u0435\u043a\u0442\u043e\u0440 \u043f\u043e\u043c\u0435\u0449\u0435\u043d\u0438\u0439"},
gtB(){return"\u041e\u043f\u0440\u0435\u0434\u0435\u043b\u0438\u0442\u0435 \u043c\u043e\u0434\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u0438 \u043c\u0435\u0431\u0435\u043b\u0438, \u0441\u0434\u0435\u043b\u0430\u043d\u043d\u044b\u0435, \u043a\u043e\u0433\u0434\u0430 \u044d\u043a\u0440\u0430\u043d \u0431\u044b\u043b \u043f\u0443\u0441\u0442."},
gnw(){return"\u0421\u0442\u0435\u043a \u043f\u043e\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u0435\u0439"},
gnv(){return"\u0420\u0435\u043a\u043e\u043d\u0441\u0442\u0440\u0443\u0438\u0440\u0443\u0439\u0442\u0435 \u0434\u043e\u0431\u0430\u0432\u043b\u0435\u043d\u0438\u0435 \u0438 \u0443\u0434\u0430\u043b\u0435\u043d\u0438\u0435 \u0441\u0442\u043e\u043f\u043a\u0438 \u043f\u043b\u0430\u0441\u0442\u0438\u043d \u043f\u043e \u043f\u043e\u0440\u044f\u0434\u043a\u0443."},
